mapper.sql:
d.is_deleted = 0 AND d.tab_type = #{query.tabType}
AND d.strategy_id != '999' AND d.channel != '全部'
AND d.big_category != '全部' AND d.small_category != '全部'

    AND d.strategy_class = #{query.strategyClass}


    AND EXISTS (SELECT 1 FROM t_sr_strategy cg
        WHERE cg.strategy_code = d.strategy_id AND cg.tab_type = 'active'
          AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
          AND cg.customer_group = #{query.customerGroup})

AND d.city_id = #{query.cityId}
AND d.county_id = #{query.countyId}

    AND (d.channel = #{query.channel} OR d.channel IN (SELECT ch.key_code FROM t_sr_dim_channel ch
        WHERE ch.key_name = #{query.channel} AND ch.status = 1 AND ch.is_deleted = 0
          AND (ch.tab_type = #{query.tabType} OR FIND_IN_SET(#{query.tabType}, ch.tab_type) > 0)))

AND d.big_category = #{query.bigCategory}
AND d.small_category = #{query.smallCategory}
AND d.strategy_name LIKE CONCAT('%', #{query.strategyName}, '%')
